BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_auditdetail" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "system_qty" decimal NOT NULL, "actual_qty" decimal NOT NULL, "diff_qty" decimal NOT NULL, "loss_reason" varchar(150) NOT NULL, "batch_id" bigint NOT NULL REFERENCES "core_batch" ("id") DEFERRABLE INITIALLY DEFERRED, "audit_id" bigint NOT NULL REFERENCES "core_inventoryaudit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_batch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "batch_code" varchar(50) NOT NULL UNIQUE, "mfg_date" date NOT NULL, "exp_date" date NOT NULL, "qty_initial" decimal NOT NULL, "qty_current" decimal NOT NULL, "unit_cost" decimal NOT NULL, "status" varchar(15) NOT NULL, "location_id" bigint NULL REFERENCES "core_location" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "core_product" ("id") DEFERRABLE INITIALLY DEFERRED, "receipt_id" bigint NULL REFERENCES "core_receipt" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(30) NOT NULL UNIQUE, "name" varchar(100) NOT NULL UNIQUE, "storage_type" varchar(10) NOT NULL, "description" text NOT NULL);
CREATE TABLE "core_customerorder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "customer_name" varchar(150) NOT NULL, "customer_phone" varchar(20) NOT NULL, "shipping_address" varchar(255) NOT NULL, "payment_method" varchar(20) NOT NULL, "payment_status" varchar(20) NOT NULL, "order_status" varchar(20) NOT NULL, "total_amount" decimal NOT NULL, "created_at" datetime NOT NULL, "note" text NOT NULL, "customer_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_customerorderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" decimal NOT NULL, "unit_price" decimal NOT NULL, "subtotal" decimal NOT NULL, "order_id" bigint NOT NULL REFERENCES "core_customerorder" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "core_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_inventoryaudit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "audit_date" date NOT NULL, "zone_name" varchar(50) NOT NULL, "status" varchar(15) NOT NULL, "note" text NOT NULL, "conducted_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_issue" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "total_amount" decimal NOT NULL, "status" varchar(15) NOT NULL, "note" text NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "partner_id" bigint NOT NULL REFERENCES "core_partner" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_issuedetail" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" decimal NOT NULL, "unit_price" decimal NOT NULL, "batch_id" bigint NOT NULL REFERENCES "core_batch" ("id") DEFERRABLE INITIALLY DEFERRED, "issue_id" bigint NOT NULL REFERENCES "core_issue" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_location" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "zone" varchar(30) NOT NULL, "shelf" varchar(30) NOT NULL, "level" varchar(30) NOT NULL, "note" varchar(150) NOT NULL);
CREATE TABLE "core_partner" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "contact_person" varchar(100) NOT NULL, "phone" varchar(20) NOT NULL, "address" varchar(255) NOT NULL, "notes" text NOT NULL);
CREATE TABLE "core_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(30) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "unit" varchar(20) NOT NULL, "safety_stock" decimal NOT NULL, "storage_temp" varchar(50) NOT NULL, "strategy" varchar(4) NOT NULL, "price" decimal NOT NULL, "is_active" bool NOT NULL, "image_url" varchar(500) NOT NULL, "category_id" bigint NOT NULL REFERENCES "core_category" ("id") DEFERRABLE INITIALLY DEFERRED, "season" varchar(20) NOT NULL, "description" text NOT NULL, "origin" varchar(150) NOT NULL, "quality_standard" varchar(100) NOT NULL, "supplier_id" bigint NULL REFERENCES "core_supplier" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_receipt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "total_amount" decimal NOT NULL, "note" text NOT NULL, "created_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "supplier_id" bigint NOT NULL REFERENCES "core_supplier" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_supplier" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "address" varchar(255) NOT NULL, "notes" text NOT NULL);
CREATE TABLE "core_userprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(30) NOT NULL, "full_name" varchar(150) NOT NULL, "phone" varchar(20) NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "address" varchar(255) NOT NULL);
CREATE TABLE "core_wastereport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "report_date" date NOT NULL, "quantity" decimal NOT NULL, "reason" varchar(20) NOT NULL, "note" text NOT NULL, "batch_id" bigint NOT NULL REFERENCES "core_batch" ("id") DEFERRABLE INITIALLY DEFERRED, "reported_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
